pages.css:
.tb-body{padding:14px 6px 4px;box-sizing:border-box;font-family:'Georgia','Times New Roman',serif;color:#1a1a1a;display:flex;flex-direction:column;gap:12px;}
.tb-chapter-label{font-family:'Poppins','Segoe UI',Arial,sans-serif;font-size:11px;font-weight:800;color:#c45a12;text-transform:uppercase;letter-spacing:1.4px;}
.tb-chapter-title{font-family:'Poppins','Segoe UI',Arial,sans-serif;font-size:22px;font-weight:800;color:#1a1a2e;border-bottom:4px solid #F5A623;padding-bottom:8px;margin-bottom:2px;}
.tb-intro{font-size:14.5px;line-height:1.6;font-style:italic;color:#3a3a3a;}
.tb-h2{font-family:'Poppins','Segoe UI',Arial,sans-serif;font-size:16px;font-weight:800;color:#E2571C;margin-top:6px;border-left:5px solid #E2571C;padding-left:8px;}
.tb-p{font-size:13.8px;line-height:1.62;}
.tb-rule{border:2px solid #F5A623;border-radius:8px;padding:10px 14px;background:#fffaf0;font-size:13.6px;line-height:1.55;}
.tb-rule b{color:#c45a12;}
.tb-def{border-left:4px solid #1a1a2e;padding:6px 12px;background:#f4f4f8;font-size:13.6px;line-height:1.55;}
.tb-def b{color:#1a1a2e;}
.tb-example{border:2px dashed #E2571C;border-radius:8px;padding:9px 14px;background:#fff8f3;font-size:13.6px;line-height:1.55;}
.tb-example b{color:#E2571C;}
.tb-tablewrap{border:2px solid #E2571C;border-radius:8px;overflow:hidden;}
.tb-table{width:100%;border-collapse:collapse;font-size:12.6px;font-family:'Poppins','Segoe UI',Arial,sans-serif;}
.tb-table th{background:#E2571C;color:#fff;padding:6px 9px;font-weight:700;text-align:left;-webkit-print-color-adjust:exact;print-color-adjust:exact;}
.tb-table td{padding:6px 9px;border-top:1px solid #f0c9a8;border-right:1px solid #f0c9a8;}
.tb-table td:last-child,.tb-table th:last-child{border-right:none;}
.tb-summary{border:2px solid #1a1a2e;border-radius:10px;padding:10px 14px;background:#1a1a2e;color:#fff;font-family:'Poppins','Segoe UI',Arial,sans-serif;}
.tb-summary b{color:#F5A623;}
.tb-summary ul{margin:6px 0 0 18px;padding:0;font-size:13px;line-height:1.6;}
.tb-titlepage{font-family:'Times New Roman',Times,serif;text-align:center;padding:26px 46px 10px;box-sizing:border-box;display:flex;flex-direction:column;justify-content:center;}
.tb-tp-line{width:90px;height:3px;background:#F5A623;margin:14px auto;border-radius:2px;}
.tb-tp-title{font-size:32px;font-weight:800;color:#1a1a2e;letter-spacing:1px;}
.tb-tp-subtitle{font-size:16px;color:#E2571C;font-style:italic;margin-top:6px;}
.tb-tp-edition{font-size:12px;font-weight:800;color:#c45a12;text-transform:uppercase;letter-spacing:1.4px;margin-top:16px;font-family:'Poppins','Segoe UI',Arial,sans-serif;}
.tb-tp-note{margin-top:22px;font-size:12px;color:#6c757d;font-style:italic;line-height:1.55;font-family:'Poppins','Segoe UI',Arial,sans-serif;padding:0 10px;}
.tb-toc{font-family:'Times New Roman',Times,serif;padding:8px 4px;box-sizing:border-box;}
.tb-toc-title{font-size:22px;font-weight:800;color:#1a1a2e;text-align:center;border-bottom:4px solid #F5A623;padding-bottom:9px;margin-bottom:6px;font-family:'Poppins','Segoe UI',Arial,sans-serif;}
.tb-toc-row{display:flex;justify-content:space-between;align-items:baseline;padding:9px 8px;border-bottom:1px dashed #dee2e6;}
